/*
 * [bud].[trg_BudgetTable_UpdateDate_Change] — LIVE definition, supplied 2026-09-24.
 * SQL_TRIGGER, AFTER UPDATE on bud.jsBudgetTable.
 * Created 2025-06-05 11:11:39.337 · Modified 2025-06-05 11:11:39.337
 * Source: sys.sql_modules.definition, copied from an SSMS results grid.
 *
 * The grid collapsed every line break into spaces, so the definition below is
 * the original text on ONE line, otherwise verbatim. Read it; do not run it —
 * the first `--` comment would comment out everything after it. For a runnable
 * copy use SSMS Tasks > Generate Scripts.
 *
 * Fires only when some statement UPDATEs bud.jsBudgetTable.UpdateDate. The live
 * InsertBudgetFromHANA only INSERTs (and skips rows that already exist), so
 * what, if anything, still performs that UPDATE is not known.
 *
 * Update 2026-09-24: the only module found that UPDATEs UpdateDate is
 * bud.jsGetBudgetSap, and nothing calls it (no module, no job, no JSAP C#).
 * So this trigger is effectively dormant: a rejected budget document is no
 * longer archived and released for re-creation when SAP changes it.
 */
CREATE TRIGGER [bud].[trg_BudgetTable_UpdateDate_Change]  ON [bud].[jsBudgetTable]  AFTER UPDATE  AS  BEGIN      SET NOCOUNT ON;            -- Check if UpdateDate column was changed      IF UPDATE(UpdateDate)      BEGIN          -- Declare variables          DECLARE @DocEntry INT, @Status VARCHAR(10), @DocID INT, @NewDocID INT;                    -- Create temp table to track processed DocEntries          CREATE TABLE #ProcessedDocEntries (DocEntry INT PRIMARY KEY);                    -- Cursor to process each UNIQUE DocEntry that was updated          DECLARE update_cursor CURSOR FOR          SELECT DISTINCT i.DocEntry          FROM inserted i          INNER JOIN deleted d ON i.DocEntry = d.DocEntry          WHERE i.UpdateDate <> d.UpdateDate -- Only process rows where UpdateDate changed          AND NOT EXISTS (SELECT 1 FROM #ProcessedDocEntries p WHERE p.DocEntry = i.DocEntry);                    OPEN update_cursor;          FETCH NEXT FROM update_cursor INTO @DocEntry;                    WHILE @@FETCH_STATUS = 0          BEGIN              -- Mark this DocEntry as processed              INSERT INTO #ProcessedDocEntries (DocEntry) VALUES (@DocEntry);                            -- Check if DocEntry exists in jsDocEntry with status 'R'              SELECT @Status = status, @DocID = id              FROM [bud].[jsDocEntry]              WHERE docEntry = @DocEntry;                            IF @Status = 'R'              BEGIN                  -- Begin transaction for data migration                  BEGIN TRANSACTION;                                    BEGIN TRY                      -- 1. Insert ALL rows from jsBudgetTable for this DocEntry into jsBudgetTableV2                      -- Only if they haven't been inserted already                      INSERT INTO [bud].[jsBudgetTableV2] (                          [Branch],                          [DocEntry],                          [ObjectName],                          [ObjType],                          [LineNum],                          [VisOrder],                          [AcctCode],                          [AcctName],                          [CardCode],                          [CardName],                          [EFFECTMONTH],                          [BUDGET],                          [SUB_BUDGET],                          [STATE],                          [DocDate],                          [CreateDate],                          [AMOUNT],                          [CURRENTMONTH],                          [Current_month_Posted_Amount],                          [Budget_Owner],                          [OwnerCode],                          [Approver Name],                          [ApprovalCode],                          [Current_month_Budget],                          [Status],                          [U_NAME],                          [CreatedDate],                          [CreateTime],                          [LineRemarks],                          [Comments],                          [ProcesStat],                          [UpdateDate],                          [OcrCode],                          [ACOMMENT],                          [VCOMMENT],                          [VerifiedStatus],                          [ApprovedStatus],                          [flag]                      )                      SELECT                           d.[Branch],                          d.[DocEntry],                          d.[ObjectName],                          d.[ObjType],                          d.[LineNum],                          d.[VisOrder],                          d.[AcctCode],                          d.[AcctName],                          d.[CardCode],                          d.[CardName],                          d.[EFFECTMONTH],                          d.[BUDGET],                          d.[SUB_BUDGET],                          d.[STATE],                          d.[DocDate],                          d.[CreateDate],                          d.[AMOUNT],                          d.[CURRENTMONTH],                          d.[Current_month_Posted_Amount],                          d.[Budget_Owner],                          d.[OwnerCode],                          d.[Approver Name],                          d.[ApprovalCode],                          d.[Current_month_Budget],                          d.[Status],                          d.[U_NAME],                          d.[CreatedDate],                          d.[CreateTime],                          d.[LineRemarks],                          d.[Comments],                          d.[ProcesStat],                          d.[UpdateDate],                          d.[OcrCode],                          d.[ACOMMENT],                          d.[VCOMMENT],                          d.[VerifiedStatus],                          d.[ApprovedStatus],                          'D' -- Flag indicating this is a deleted/archived record                      FROM deleted d                      WHERE d.DocEntry = @DocEntry                      AND NOT EXISTS (                          SELECT 1                           FROM [bud].[jsBudgetTableV2] v2                           WHERE v2.DocEntry = d.DocEntry                           AND v2.LineNum = d.LineNum                          AND v2.VisOrder = d.VisOrder                          AND v2.flag = 'D'                      );                                            -- 2. Check if jsDocEntry record exists and hasn't been migrated yet                      IF EXISTS (SELECT 1 FROM [bud].[jsDocEntry] WHERE id = @DocID)                      BEGIN                          -- Insert data into jsDocEntryV2 from jsDocEntry                          INSERT INTO [bud].[jsDocEntryV2] (                              docEntry,                              status,                              currentStageId,                              templateId,                              totalStage,                              currentSatge,                              date,                              updatedOn,                              createdOn                          )                          SELECT                               docEntry,                              status,                              currentStageId,                              templateId,                              totalStage,                              currentSatge,                              date,                              updatedOn,                              createdOn                          FROM [bud].[jsDocEntry]                          WHERE id = @DocID;                                                    -- Get the newly generated ID if needed for related tables                          SET @NewDocID = SCOPE_IDENTITY();                                                    -- 3. Insert data into jsDocEnrtyDetailV2 from jsDocEnrtyDetail                          INSERT INTO [bud].[jsDocEnrtyDetailV2] (                              objType,                              company,                              lineNum,                              visOrder,                              docId                          )                          SELECT                               objType,                              company,                              lineNum,                              visOrder,                              CASE                                   WHEN @NewDocID IS NOT NULL THEN @NewDocID                                   ELSE docId                               END                          FROM [bud].[jsDocEnrtyDetail]                          WHERE docId = @DocID;                                                    -- 4. Insert data into jsBudgetStatusWorkflowV2 from jsBudgetStatusWorkflow                          INSERT INTO [bud].[jsBudgetStatusWorkflowV2] (                              docId,                              status,                              stageId,                              templateId,                              userId,                              createdOn,                              description                          )                          SELECT                               CASE                                   WHEN @NewDocID IS NOT NULL THEN @NewDocID                                   ELSE docId                               END,                              status,                              stageId,                              templateId,                              userId,                              createdOn,                              description                          FROM [bud].[jsBudgetStatusWorkflow]                          WHERE docId = @DocID;                                                    -- 6. Delete from jsDocEnrtyDetail                          DELETE FROM [bud].[jsDocEnrtyDetail]                          WHERE docId = @DocID;                                                    -- 7. Delete from jsBudgetStatusWorkflow                          DELETE FROM [bud].[jsBudgetStatusWorkflow]                          WHERE docId = @DocID;                                                    -- 8. Delete from jsDocEntry                          DELETE FROM [bud].[jsDocEntry]                          WHERE id = @DocID;                      END                                            COMMIT TRANSACTION;                  END TRY                  BEGIN CATCH                      ROLLBACK TRANSACTION;                                            -- Log error or raise it                      DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();                      DECLARE @ErrorSeverity INT = ERROR_SEVERITY();                      DECLARE @ErrorState INT = ERROR_STATE();                                            RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);                  END CATCH;              END                            FETCH NEXT FROM update_cursor INTO @DocEntry;          END                    CLOSE update_cursor;          DEALLOCATE update_cursor;                    -- Clean up temp table          DROP TABLE #ProcessedDocEntries;      END  END;
